// admitGitLabGenerationFlags keeps GitHub-only orchestration out of the
// GitLab generation route, before selecting a plugin or opening its inputs.
// Provider admission, generated bytes and execution remain factory-owned.
func admitGitLabGenerationFlags(c *cli.Context) error {
	if !strings.EqualFold(strings.TrimSpace(c.String("engine")), factory.EngineGitLab) {
		return nil
	}
	for _, selection := range []struct {
		name     string
		selected bool
	}{
		{"runtime", c.Bool("runtime")},
		{"source-commit", c.IsSet("source-commit")},
		{"projection-pilot", c.IsSet("projection-pilot")},
		{"qualification-policy", c.IsSet("qualification-policy")},
	} {
		if selection.selected {
			return e.New(e.CodeEngineCapability, "GitLab generation does not support --%s", selection.name)
		}
	}
	return nil
}

// gitLabJobFromEnvironment decodes the native context's canonical framing.
// These values describe a selection only: factory's provider owner must still
// authenticate the actual current job and every original producer carrier.
func gitLabJobFromEnvironment(getenv func(string) string) (factory.GitLabJobContext, error) {
	var job factory.GitLabJobContext
	for _, field := range []struct {
		name string
		out  *uint64
	}{
		{"CI_PROJECT_ID", &job.ProjectID},
		{"CI_PIPELINE_ID", &job.PipelineID},
		{"CI_JOB_ID", &job.JobID},
	} {
		raw := getenv(field.name)
		value, err := strconv.ParseUint(raw, 10, 64)
		if err != nil || value == 0 || strconv.FormatUint(value, 10) != raw {
			return factory.GitLabJobContext{}, e.New(e.CodeUsage, "GitLab execution requires canonical %s", field.name)
		}
		*field.out = value
	}
	job.Commit = getenv("CI_COMMIT_SHA")
	if len(job.Commit) != 40 {
		return factory.GitLabJobContext{}, e.New(e.CodeUsage, "GitLab execution requires canonical CI_COMMIT_SHA")
	}
	decoded, err := hex.DecodeString(job.Commit)
	if err != nil || len(decoded) != 20 || hex.EncodeToString(decoded) != job.Commit {
		return factory.GitLabJobContext{}, e.New(e.CodeUsage, "GitLab execution requires canonical CI_COMMIT_SHA")
	}
	job.Ref = getenv("CI_COMMIT_REF_NAME")
	job.Source = getenv("CI_PIPELINE_SOURCE")
	for _, selection := range []struct{ name, value string }{
		{"CI_COMMIT_REF_NAME", job.Ref}, {"CI_PIPELINE_SOURCE", job.Source},
	} {
		if selection.value == "" || strings.TrimSpace(selection.value) != selection.value || strings.ContainsAny(selection.value, "\r\n\x00") {
			return factory.GitLabJobContext{}, e.New(e.CodeUsage, "GitLab execution requires canonical %s", selection.name)
		}
	}
	return job, nil
}

func cmdFactoryGitLab() *cli.Command {
	return &cli.Command{Name: "gitlab", Hidden: true, Usage: "execute exact generated GitLab operations", Subcommands: []*cli.Command{{
		Name: "run-node", Hidden: true,
		Flags: []cli.Flag{&cli.StringFlag{Name: "plan", Required: true}, &cli.StringFlag{Name: "node", Required: true}, &cli.StringFlag{Name: "root", Value: "."}},
		Action: func(c *cli.Context) error {
			if c.Args().Present() || c.String("root") == "" {
				return e.New(e.CodeUsage, "GitLab run-node requires its exact Plan, node and root without positional arguments")
			}
			job, err := gitLabJobFromEnvironment(os.Getenv)
			if err != nil {
				return err
			}
			plan, err := factory.LoadPlanContext(c.Context, c.String("plan"))
			if err != nil {
				return err
			}
			return factory.RunGitLabNode(c.Context, plan, c.String("node"), factory.GitLabNodeOptions{
				Root: c.String("root"), Job: job, Stdout: c.App.Writer, Stderr: c.App.ErrWriter,
			})
		},
	}}}
}

func cmdRunFinalizeGitLab() *cli.Command {
	return &cli.Command{Name: "finalize-gitlab", Hidden: true, Usage: "finalize one unqualified native GitLab Run from its exact original outcomes",
		Flags: append(lifecycleInputFlags(), &cli.StringFlag{Name: "plan", Required: true},
			&cli.StringFlag{Name: "workspace", Value: ".nvkr/factory"}, &cli.StringFlag{Name: "out", Value: ".nvkr/run.json"}),
		Action: func(c *cli.Context) error {
			if c.Args().Present() {
				return e.New(e.CodeUsage, "GitLab finalization accepts flags only")
			}
			job, err := gitLabJobFromEnvironment(os.Getenv)
			if err != nil {
				return err
			}
			run, err := lifecycle.FinalizeGitLab(c.Context, c.String("definition"), c.String("environment"), c.String("plan"),
				factoryGeneratorVersion(), c.String("workspace"), c.String("out"), job)
			if err != nil {
				return err
			}
			_, err = fmt.Fprintf(c.App.Writer, "GitLab Run %s: %s (%d observed outputs; %s)\n", run.Attempt, run.Status, len(run.Observed), run.Lane)
			if err != nil {
				return e.Wrap(e.CodeInternal, err, "writing GitLab Run description")
			}
			return nil
		},
	}
}
